// ---- PASS B station steps (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py) ----

StationStep networkRxIfbRecoupleEdge(StationBuild& build) {
    // ---- From the station build (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    const NetworkRunContext& ctx = build.ctx;
    const int i = build.i;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    // ---- End of the bindings ----

    // Card L5B: the re-coupling edge of an estimated receiver IFB (invariant #7).  A
    // governed column back in the block after at least one loop epoch out of it,
    // with its carry entry still live, re-couples through that entry's stored
    // regression; counted, since its coupling row is gauge-restored per
    // (constellation, kind) and not per signal.  The carry map is read-only here.
    if (!ctx.param_inventory.rx_ifb.estimated_by_knob) return StationStep::Next;
    const long long ep = static_cast<long long>(ctx.counters.n_loop_epochs);
    for (const auto& [cb_key, cb_sidx] : st.sm->getCodeBiasStates()) {
        if (!h2local.count(static_cast<int>(cb_sidx))) continue;
        const auto id = classifyStateColumn(StateContainer::CodeBiasStates, cb_key);
        if (!id || !RxIfbRule::governs(id->cls)) continue;
        const auto lit = st.l5b.last_est_epoch.find(cb_key);
        if (lit != st.l5b.last_est_epoch.end() && lit->second < ep - 1
            && ctx.carry.rx_cb_carry.count({static_cast<int>(i), cb_key}))
            ++st.l5b.recouple;
        st.l5b.last_est_epoch[cb_key] = ep;
    }
    // The observation's own signal of every data row travels in its row tag
    // (R.row_tags, set by the split): the post-fit row writer reads it there
    // (card OWD, O5; card NOM step N2b).
    return StationStep::Next;
}

void networkRxCbBlockColumns(StationCarryFrame& carry) {
    // ---- From the station build (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    StationBuild& build = carry.build;
    const NetworkRunContext& ctx = build.ctx;
    double pl_now_s = build.clock.pl_now_s;
    const int i = build.i;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    const bool legacy_local_inject = carry.legacy_local_inject;
    const bool do_amb_carry = carry.do_amb_carry;
    const Eigen::VectorXd& x_lin = carry.x_lin;
    // The alias lines of networkPassB_ this function reads, verbatim (card NOM3 step PB1b).
    const double rx_cb_q       = ctx.knobs.rx_cb_q;              // rx-CB carry RW process noise (m²/s)
    // RXCB-IN-BLOCK (card CTU section 14): the rx-CB columns ride the station's local
    // block with their border regression; the diagonal fold below is then skipped for
    // every station-epoch (no diagonal fallback, as for the receiver clock).  The
    // loader guarantees the carry, the coupling rows and a local block; pl_blk_on is the
    // live half of that gate.
    const bool   rxcb_blk_on   = ctx.knobs.rxcb_blk_on;
    auto& rx_cb_carry = ctx.carry.rx_cb_carry;   // rx-CB carry: produce phase reads only
    // ---- End of the bindings ----

    if (!(legacy_local_inject && do_amb_carry)) return;
    // RXCB-IN-BLOCK (card CTU section 14): the station's carried receiver
    // code-bias columns as more columns of the same block.  The diagonal fold
    // at the conditional variance (N_rr^-1)_cc states the column given the
    // shared border as if it were known absolutely, so each epoch it
    // re-asserts the border along the column's regression on top of the dense
    // border carry that already holds that information (the level
    // information doubled per epoch on the sim bed).  Here the column is a
    // card 1 coupling row (its regression on the border is harvested with
    // it) and its overlap with the station's ambiguities is the harvested
    // cross covariance.  The inject decision is the carry's gap bound
    // (rxCbInjectGate with the innovation test off): the diagonal route's
    // inject screen |value_abs - x_lin| compares the carry with a frozen
    // linearization point, so it withholds a station with a large bias for the
    // whole run (4 of 60 sim stations) and cannot see a jump between two
    // epochs.  The event response is the frame-invariant step between two
    // harvested absolutes, at the harvest (the receiver clock's rule).  The
    // carry map is read-only here; the columns point at the entries.
    std::vector<LocalBlockCol>& rxcb_bc = carry.rxcb_bc;
    // Card L5B: which of rxcb_bc are receiver IFB columns, for the fold count
    // (filled only when network.estimate_rx_extra_band_code_delay is effective).
    std::vector<char>& rxcb_ifb = carry.rxcb_ifb;
    if (rxcb_blk_on) {
        for (const auto& [cb_key, cb_sidx] : st.sm->getCodeBiasStates()) {
            if (StateKeys::isGlonassPerSlotIfbKey(cb_key)) continue;  // anchored family
            const int cb_idx = static_cast<int>(cb_sidx);
            if (cb_idx < 0 || cb_idx >= x_lin.size()) continue;
            if (!std::isfinite(x_lin(cb_idx))) continue;
            const auto cbhit = h2local.find(cb_idx);
            if (cbhit == h2local.end()) continue;
            const auto cbit = rx_cb_carry.find({static_cast<int>(i), cb_key});
            if (cbit == rx_cb_carry.end()) continue;   // cold: the harvest seeds it
            // An entry with no harvest-block row was not harvested on this
            // route (a warm resume restored it from a diagonal-carry
            // snapshot): without its regression it would state the border
            // absolutely, the double count this route removes.  It is left out
            // and re-harvested this epoch (counted).
            if (!cbit->second.blk) { ++R.pl_rxcb_restored_skip; continue; }
            double cb_var_eff = 0.0;
            const RxCbInjectAction act = rxCbInjectGate(
                pl_now_s - cbit->second.last_seen_s, /*max_gap_s=*/kRxCbMaxGapS,
                cbit->second.var, rx_cb_q, cbit->second.value_abs - x_lin(cb_idx),
                /*k_sigma=*/10.0, /*guard_var=*/0.25, cb_var_eff,
                /*innov_test=*/false);
            if (act != RxCbInjectAction::Fold) {
                // Card PRM phase 3a: the horizon's skip only, not the gate's
                // variance guard (which returns the same action).
                if (carryPastHorizon(pl_now_s, cbit->second.last_seen_s, kRxCbMaxGapS))
                    ++R.prm_rxcb_gap_skip;
                continue;
            }
            rxcb_bc.push_back(LocalBlockCol{
                static_cast<Eigen::Index>(cbhit->second), x_lin(cb_idx),
                &cbit->second, cb_var_eff,
                std::max(0.0, pl_now_s - cbit->second.last_seen_s),
                /*vce_fac=*/1.0, /*is_zwd=*/false, /*is_iono=*/false,
                /*is_rx_clk=*/false, /*is_rx_isb=*/false,
                /*is_rx_cb=*/true});
            rxcb_bc.back().signal = rxCodeBiasSignal(cb_key);   // its block row's tag (card NOM N2a)
            if (ctx.param_inventory.rx_ifb.estimated_by_knob) {
                const auto id = classifyStateColumn(StateContainer::CodeBiasStates, cb_key);
                rxcb_ifb.resize(rxcb_bc.size(), 0);
                rxcb_ifb.back() = (id && RxIfbRule::governs(id->cls)) ? 1 : 0;
            }
        }
    }
}

void networkRxCbPriors(StationCarryFrame& carry) {
    // ---- From the station build (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    StationBuild& build = carry.build;
    const NetworkRunContext& ctx = build.ctx;
    double pl_now_s = build.clock.pl_now_s;
    const int i = build.i;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    const Eigen::VectorXd& x_lin = carry.x_lin;
    std::vector<std::tuple<Eigen::Index, double, double, RowTag>>& inj = carry.inj;
    std::vector<std::tuple<Eigen::Index, double, double, RowTag>>& inj_prior = carry.inj_prior;
    // The alias lines of networkPassB_ this function reads, verbatim (card NOM3 step PB1b).
    const bool   rx_cb_on      = ctx.knobs.rx_cb_on;             // rx-CB carry (SPEC_rx_cb_carry)
    const bool   rx_cb_datum  = ctx.knobs.rx_cb_datum;           // zero-mean-over-receivers DCB datum (RXCB-DATUM; shares the pl_cb walk with the carry)
    const double rx_cb_datum_sigma = ctx.knobs.rx_cb_datum_sigma; // loose physical-bound sigma of RXCB-DATUM (m)
    const bool   sta_prior_pre_pd = ctx.knobs.sta_prior_pre_pd;   // route the RXCB-DATUM rows to the pre-PD fold (RF-PD-fix)
    const double rx_cb_q       = ctx.knobs.rx_cb_q;              // rx-CB carry RW process noise (m²/s)
    // RXCB-IN-BLOCK (card CTU section 14): the rx-CB columns ride the station's local
    // block with their border regression; the diagonal fold below is then skipped for
    // every station-epoch (no diagonal fallback, as for the receiver clock).  The
    // loader guarantees the carry, the coupling rows and a local block; pl_blk_on is the
    // live half of that gate.
    const bool   rxcb_blk_on   = ctx.knobs.rxcb_blk_on;
    auto& rx_cb_carry = ctx.carry.rx_cb_carry;   // rx-CB carry: produce phase reads only
    // ---- End of the bindings ----

    // --- rx-CB carry (docs/SPEC_rx_cb_carry.md): receiver code-bias
    //     columns as carried RW priors.  Outside the legacy gate above, so
    //     it is live on the carry_invariant / no-leveling lineage.  The
    //     carry map is read-only here (parallel produce phase); decisions
    //     are counted in R and the serial harvest applies every consequence
    //     (a stale-entry overwrite is the implicit drop).  Diagonal fold
    //     even under carry_cpl_cond, for the RPB reason: a coupling row
    //     would hand a strictly local hardware state a shared-border
    //     footprint.
    // RXCB-DATUM shares this walk: the receiver code-bias datum needs the
    // same (key, A_r column) records the carry collects, so pl_cb is filled
    // whenever either is armed and only the carry-injection half below stays
    // behind rx_cb_on.  (The post-solve harvest that consumes pl_cb is itself
    // gated on rx_cb_on, so a datum-only run fills the vector and nothing
    // harvests it, as intended.)
    if (!(rx_cb_on || rx_cb_datum)) return;
    for (const auto& [cb_key, cb_sidx] : st.sm->getCodeBiasStates()) {
        if (StateKeys::isGlonassPerSlotIfbKey(cb_key)) continue;  // anchored family
        const int cb_idx = static_cast<int>(cb_sidx);
        if (cb_idx < 0 || cb_idx >= x_lin.size()) continue;
        if (!std::isfinite(x_lin(cb_idx))) continue;
        const auto cbhit = h2local.find(cb_idx);
        if (cbhit == h2local.end()) continue;
        const Eigen::Index cbcol = static_cast<Eigen::Index>(cbhit->second);
        R.pl_cb.emplace_back(cb_key, cbcol, x_lin(cb_idx));
        // --- RXCB-DATUM: loose zero-mean prior on the receiver DCB ----
        // The receiver-side counterpart of the W6 satellite code-bias
        // sum-to-zero, realized pre-reduce through the same diagonal
        // prior channel Card KP uses for satellite OSBs, not as a
        // post-reduce cross-station SumZeroGauge: NetworkEstimator::solve
        // correctly refuses to compose a post-reduce Woodbury gauge with
        // the Card-4 DD priors (both fold against the same cached local
        // factors; ambiguities and code biases are correlated through the
        // observation rows, so "disjoint columns" does not make it exact).
        //
        // Why a diagonal prior acts as a datum here: d_r ~ N(0, sigma^2)
        // on every station adds 1/sigma^2 along every direction of the
        // DCB subspace.  The between-station differences are estimable
        // and carry orders of magnitude more data information, so the
        // prior does not move them; the common mode has essentially none,
        // so the prior alone determines it and sets it to
        // zero-mean-over-receivers, which is the IGS DCB convention.  The
        // realized common-mode eigenvalue is 1/sigma^2, independent of the
        // station count (u = 1/sqrt(N) * 1 gives u^T (Lambda I) u =
        // Lambda), the same N-independence the broadcast-anchored clock
        // datum documents.
        //
        // The target is the absolute zero, so in the local block's
        // delta-around-x_lin coordinates the RHS is -Lambda * x_lin, the
        // same convention the rx-CB carry's innovation uses.
        if (rx_cb_datum && StateKeys::parseDcbKey(cb_key)) {
            const double lam = 1.0 / (rx_cb_datum_sigma * rx_cb_datum_sigma);
            const double eta = lam * (0.0 - x_lin(cb_idx));
            if (std::isfinite(lam) && std::isfinite(eta)) {
                // With station_prior_before_pd (card RF-PD-fix) the datum
                // rows leave the carry vector entirely and go to the
                // pre-PD fold instead, so addStation's PD test sees the
                // row that gauges this station's receiver DCB.  They must
                // not appear in both: addStationPrior does not sum with
                // what addStation already folded.  Off, this is the
                // original emplace at the original point in the walk, so
                // the coalesce order and every byte downstream are
                // unchanged.
                if (sta_prior_pre_pd)
                    inj_prior.emplace_back(cbcol, lam, eta,
                                           RowTag{ContributionKind::PriorRxCbDatumPrePd, {}, {}});
                else
                    inj.emplace_back(cbcol, lam, eta,
                                     RowTag{ContributionKind::PriorRxCbDatum, {}, {}});
                ++R.pl_cb_datum_rows;
            }
        }
        if (!rx_cb_on) continue;   // datum-only: record the column, carry nothing
        // RXCB-IN-BLOCK: the carry folded (or deliberately did not) in the
        // block above; there is no diagonal row on this route.
        if (rxcb_blk_on) continue;
        const auto cbit = rx_cb_carry.find({static_cast<int>(i), cb_key});
        if (cbit == rx_cb_carry.end()) continue;   // cold: the harvest seeds it
        // Card L5B: a receiver IFB column's folds and withholds on this route,
        // counted at its own station (nothing is counted unless the knob is
        // effective).
        bool cb_is_ifb = false;
        if (ctx.param_inventory.rx_ifb.estimated_by_knob) {
            const auto id = classifyStateColumn(StateContainer::CodeBiasStates, cb_key);
            cb_is_ifb = id && RxIfbRule::governs(id->cls);
        }
        double cb_var_eff = 0.0;
        const double cb_innov = cbit->second.value_abs - x_lin(cb_idx);
        const RxCbInjectAction act = rxCbInjectGate(
            pl_now_s - cbit->second.last_seen_s, /*max_gap_s=*/kRxCbMaxGapS,
            cbit->second.var, rx_cb_q, cb_innov,
            /*k_sigma=*/10.0, /*guard_var=*/0.25, cb_var_eff);
        if (act == RxCbInjectAction::SkipInnov) {
            ++R.pl_cb_innov_skips;   // receiver-reset response: withhold, harvest re-seeds
            ++R.prm_rxcb_jump_skip;  // card PRM phase 3a
            if (cb_is_ifb) ++st.l5b.diag_innov_skips;
            continue;
        }
        if (act != RxCbInjectAction::Fold) {
            // Card PRM phase 3a: the horizon's skip only, not the gate's
            // variance guard (which returns the same action).
            if (carryPastHorizon(pl_now_s, cbit->second.last_seen_s, kRxCbMaxGapS))
                ++R.prm_rxcb_gap_skip;
            continue;
        }
        const double cb_lambda = 1.0 / cb_var_eff;
        const double cb_eta = cb_lambda * cb_innov;
        if (!std::isfinite(cb_eta)) continue;
        inj.emplace_back(cbcol, cb_lambda, cb_eta,
                         rxCodeBiasTag(ContributionKind::PriorRxCbCarry, cb_key));
        ++R.pl_cb_injected;
        if (cb_is_ifb) ++st.l5b.diag_folds;
    }
}

// ---- End of the PASS B station steps (card NOM3 step PB1b) ----

// ---- Harvest half (card NOM3 step HV1; generated by scripts/nom_hv1_cut.py) ----

void networkHarvestRxCbBlock(NetworkRun& run, const NetworkEpoch& ep, HarvestBorder& border,
                             const std::vector<StationHarvestBlock>& blocks) {
    // ---- From the run, the epoch and the harvest (card NOM3 step HV1; generated by
    //      scripts/nom_hv1_cut.py, each line checked by scripts/nom_hv1_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    const NetworkEstimator& est = run.engines.est;
    const Eigen::VectorXd& x_s = ep.solve.x_s;
    std::vector<NetStation>& stations = run.setup.stations;
    const std::vector<int>& est_index_of = ep.assembly.est_index_of;
    const std::vector<StationAssembly>& asm_res = ep.assembly.asm_res;
    double pl_now_s = ep.clock.pl_now_s;
    // RXCB-IN-BLOCK (network.carry_rx_code_bias_in_block, card CTU section 14): the
    // receiver code-bias columns join the same harvest block and are stashed with their
    // border regression and block row here; the standalone diagonal harvest below then
    // skips its stash.  Off => `cols` is untouched (byte-identical).
    const bool   rxcb_blk_on   = ctx.knobs.rxcb_blk_on;
    SharedHistoryHarvest& shx_h = border.shx_h;
    // ---- End of the bindings ----
    // --- RXCB-IN-BLOCK (card CTU section 14): harvest the receiver code biases -
    //     with their border regression and their row of the station's harvest
    //     block, so next epoch's inject folds them as coupling rows of the same
    //     whitened block as the ambiguities.  The value is the posterior absolute
    //     (x_lin + x_r), the variance the pure conditional (N_rr^-1)_cc, exactly as
    //     for every other block column.  The standalone diagonal harvest further
    //     down skips its stash under this knob (it still sums the produce counters
    //     and runs the gap prune).
    if (!rxcb_blk_on) return;
    auto& rx_cb_carry = ctx.carry.rx_cb_carry;
    for (size_t i = 0; i < stations.size(); ++i) {
        if (est_index_of[i] < 0) continue;
        const StationAssembly& R = asm_res[i];
        if (R.pl_cb.empty()) continue;
        const std::size_t est_idx = static_cast<std::size_t>(est_index_of[i]);
        const std::shared_ptr<PlHarvestBlock> cblk = blocks[i].segmentBlock(BlockSegment::RxCodeBias);
        const std::vector<Eigen::Index>* ccross_cols =
            cblk ? &blocks[i].cols : nullptr;
        const Eigen::Index crow0 = cblk ? blocks[i].rowOf(BlockSegment::RxCodeBias) : Eigen::Index{-1};
        Eigen::VectorXd xr;
        try { xr = est.reconstructStation(est_idx, x_s); } catch (...) { continue; }
        for (std::size_t a = 0; a < R.pl_cb.size(); ++a) {
            const auto& [cb_key, ccol, cx_lin] = R.pl_cb[a];
            if (ccol < 0 || ccol >= xr.size()) continue;
            const double value_abs = cx_lin + xr(ccol);
            if (!std::isfinite(value_abs)) continue;
            Eigen::VectorXd ccross;
            auto hc = networkHarvestColumn(run, ep, border, est_idx, ccol, ccross_cols,
                                                            cblk ? &ccross : nullptr);
            const double var = hc.first;
            if (!(var > 0.0) || !std::isfinite(var)) {
                ++ctx.counters.n_rxcb_blk_harvest_fail;
                continue;
            }
            const auto key = std::make_pair(static_cast<int>(i), cb_key);
            // Card L5B: the satellite sum-to-zero of this receiver IFB's family
            // re-seeded this epoch (no veteran satellite), so the satellite side
            // realizes a new level of the family's null direction while a carried
            // entry holds the old one.  Erase it (reset, not repair; counted) and
            // skip this epoch's stash, whose posterior folded the old level: the
            // next harvest re-seeds from a solve the stale entry no longer reaches.
            // A column with no entry carried no old level and is stashed as usual
            // (the cold start, where every channel seeds, is that case).
            if (ctx.param_inventory.rx_ifb.estimated_by_knob
                && rxIfbFamilyReseeded(stations[i].l5b, cb_key,
                                       ctx.carry.this_epoch_cb_reseed_channels)
                && rx_cb_carry.erase(key) > 0) {
                ++stations[i].l5b.reseed_erase;
                continue;
            }
            // Event response (invariant #1): the step between this harvest's
            // absolute and the carried one, against both variances, the random
            // walk over the gap and the diagonal route's 0.5 m guard, at 10 sigma.
            // Frame-invariant (two absolute realizations), unlike the inject
            // screen it replaces.  A step erases the entry (reset, not repair):
            // this epoch folded the stale prior, so its posterior is suspect too,
            // and the next harvest re-seeds from a free solve.
            {
                const auto sit = rx_cb_carry.find(key);
                if (sit != rx_cb_carry.end()) {
                    const double sgap = pl_now_s - sit->second.last_seen_s;
                    if (sgap >= 0.0 && sgap <= kRxCbMaxGapS) {
                        const double sv = var + sit->second.var
                                          + ctx.knobs.rx_cb_q * sgap + 0.25;
                        if (std::abs(value_abs - sit->second.value_abs)
                            > 10.0 * std::sqrt(sv)) {
                            rx_cb_carry.erase(sit);
                            ++ctx.counters.n_rxcb_blk_step_reset;
                            prmRespond(ctx.counters.prm_resp, ResponseSite::RxcbStepErase);   // card PRM phase 3a
                            continue;
                        }
                    }
                }
            }
            LocalCarry ent{value_abs, var, pl_now_s, std::move(hc.second)};
            const auto oit = rx_cb_carry.find(key);
            const LocalCarry* cprev = (oit != rx_cb_carry.end()) ? &oit->second : nullptr;
            ent.var_first = cprev ? cprev->var_first : var;
            localCarryStampBirth(
                ent, cprev, static_cast<long long>(ctx.counters.n_loop_epochs), pl_now_s);
            // Row crow0 + a of the station's harvest block is this column's n_c read
            // at every carried column of the station, so next epoch's block pairs
            // it with the ambiguities by pointer equality.
            bool in_blk = false;
            if (cblk && crow0 >= 0 && ccross.size() == cblk->C.rows()) {
                const Eigen::Index crow = crow0 + static_cast<Eigen::Index>(a);
                if (crow < cblk->C.rows()) {
                    cblk->C.row(crow) = ccross.transpose();
                    ent.blk     = cblk;
                    ent.blk_idx = static_cast<int>(crow);
                    in_blk = true;
                }
            }
            if (!in_blk) ++ctx.counters.n_rxcb_blk_no_block;
            rx_cb_carry[key] = std::move(ent);
            networkSharedHistoryNoteEntry(shx_h, est_idx, ccol, SharedHistoryMap::RxCb,
                                          static_cast<int>(i), cb_key);   // card SCL2 X2; no-op off
            ++ctx.counters.n_rxcb_blk_harvested;
            ++ctx.counters.rx_cb_harvested_total;
        }
    }
}

void networkRxCbDatumGaugeCensus(NetworkRun& run, const NetworkEpoch& ep) {
    // ---- From the run, the epoch and the harvest (card NOM3 step HV1; generated by
    //      scripts/nom_hv1_cut.py, each line checked by scripts/nom_hv1_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    std::vector<NetStation>& stations = run.setup.stations;
    const std::vector<int>& est_index_of = ep.assembly.est_index_of;
    const std::vector<StationAssembly>& asm_res = ep.assembly.asm_res;
    // ---- End of the bindings ----
    // --- Receiver-DCB datum gauge census (RXCB-DATUM) --------------------------
    // The zero-mean receiver-DCB datum's fold count, in its own walk, gated on its own
    // knob.  network.rx_code_bias_datum and network.carry_rx_code_bias are independent,
    // and the datum without the carry is the canonical posture; counting this inside
    // the carry bracket below would leave n_rxcb_gauges at 0 on every such run, and the
    // run-end RXCB-DATUM line would then raise its invariant #4 alarm against a working
    // gauge.
    //
    // This is the only accumulation site, so a run with both armed cannot double count.
    // It is also byte-identical on the carry-only posture: R.pl_cb_datum_rows is
    // incremented only under `rx_cb_datum` (the RXCB-DATUM row build in
    // ApplicationNetworkAssembly.cpp), so it is 0 whenever this walk is skipped.
    if (!ctx.knobs.rx_cb_datum) return;
    for (size_t i = 0; i < stations.size(); ++i) {
        if (est_index_of[i] < 0) continue;
        ctx.counters.n_rxcb_gauges +=
            static_cast<size_t>(asm_res[i].pl_cb_datum_rows);
    }
}

void networkHarvestRxCbCarry(NetworkRun& run, const NetworkEpoch& ep) {
    // ---- From the run, the epoch and the harvest (card NOM3 step HV1; generated by
    //      scripts/nom_hv1_cut.py, each line checked by scripts/nom_hv1_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    const NetworkEstimator& est = run.engines.est;
    const Eigen::VectorXd& x_s = ep.solve.x_s;
    std::vector<NetStation>& stations = run.setup.stations;
    const std::vector<int>& est_index_of = ep.assembly.est_index_of;
    const std::vector<StationAssembly>& asm_res = ep.assembly.asm_res;
    const NetworkSbasis::Plan& plan = ep.solve.plan;
    NetworkPriorResidual& prires_est = run.engines.prires;
    double pl_now_s = ep.clock.pl_now_s;
    const bool   prires_rxcb = ctx.knobs.prires_rxcb;
    // ---- End of the bindings ----
    // --- rx-CB carry: harvest, stash and prune -------------------------------
    // Outside the carry_warm bracket above on purpose: the receiver code-bias carry has
    // to be live on the carry_invariant lineage without phase leveling (the carry_warm
    // gate is what makes the ZWD carry inert there).  Mirrors the RPB harvest: several
    // columns per station, conditional local variance, LocalCarry stash keyed
    // (station, CB key).  The produce phase only reads the map (find, never insert or
    // erase) and counts its decisions in R, which are summed here serially, so the whole
    // cycle is race-free by construction.
    if (!ctx.knobs.rx_cb_on) return;
    auto& rx_cb_carry = ctx.carry.rx_cb_carry;
    // The horizon is kRxCbMaxGapS (filter/NetworkRunTypes.hpp; spec §3: housekeeping
    // horizon), the one definition the inject, this harvest and the registry read.
    for (size_t i = 0; i < stations.size(); ++i) {
        if (est_index_of[i] < 0) continue;
        const StationAssembly& R = asm_res[i];
        ctx.counters.rx_cb_injected_total += R.pl_cb_injected;
        // n_rxcb_gauges is not summed here: it belongs to the RXCB-DATUM knob, not
        // the carry, and has its own walk above.  Every counter left in this bracket
        // is carry-only: their producer-side increments all sit below the
        // `if (!rx_cb_on) continue;` in the assembly's pl_cb walk, so a datum-only run
        // cannot populate them.
        ctx.counters.rx_cb_innov_skips_total += R.pl_cb_innov_skips;
        // The same two tallies, kept per station (RS-9 rider, §21.18).  The pooled
        // "N folded, M withheld" line cannot tell a share of stations refused
        // occasionally from a similar share refused always; in the second case the set
        // is fixed from k = 1, and those stations carry no receiver-DCB memory for the
        // whole run while the line still counts them among the "N carried".  The
        // denominator is station-epochs with a decision; the numerator is
        // station-epochs in which every decision was a withhold ("carried nothing",
        // the multi-family generalization of the one-key field posture).  Serial, so
        // no race.
        if (R.pl_cb_injected > 0 || R.pl_cb_innov_skips > 0) {
            auto& tally = ctx.counters.rx_cb_sta_tally[stations[i].name];
            ++tally.first;
            if (R.pl_cb_injected == 0) ++tally.second;
        }
        // RXCB-IN-BLOCK: the stash happened in the block harvest above (with the
        // border regression), and only while the leveling carry is warm; a cold
        // entry must not be written here without one.
        if (ctx.knobs.rxcb_blk) continue;
        if (R.pl_cb.empty()) continue;
        const std::size_t est_idx = static_cast<std::size_t>(est_index_of[i]);
        Eigen::VectorXd xr, vard;
        std::vector<Eigen::Index> cols;
        cols.reserve(R.pl_cb.size());
        for (const auto& t : R.pl_cb) cols.push_back(std::get<1>(t));
        try {
            xr = est.reconstructStation(est_idx, x_s);
            vard = est.conditionalLocalVarianceDiag(
                est_idx, cols, plan.shared_datum);
        } catch (...) { continue; }
        for (std::size_t a = 0; a < R.pl_cb.size(); ++a) {
            const auto& [cb_key, ccol, cx_lin] = R.pl_cb[a];
            if (ccol < 0 || ccol >= xr.size()) continue;
            const double value_abs = cx_lin + xr(ccol);
            const double var = (a < static_cast<std::size_t>(vard.size()))
                                   ? vard(a) : -1.0;
            if (!std::isfinite(value_abs) || !(var > 0.0)
                || !std::isfinite(var)) continue;
            // Card L5B: a re-seeded family's carried receiver IFB entries are erased and
            // not re-stashed this epoch, as in the block harvest above (reset, not
            // repair; counted).
            if (ctx.param_inventory.rx_ifb.estimated_by_knob
                && rxIfbFamilyReseeded(stations[i].l5b, cb_key,
                                       ctx.carry.this_epoch_cb_reseed_channels)
                && rx_cb_carry.erase({static_cast<int>(i), cb_key}) > 0) {
                ++stations[i].l5b.reseed_erase;
                continue;
            }
            // Prior-residual census hook (INC-2).  `folded` is re-derived by calling
            // rxCbInjectGate with the same arguments PASS B used: the gate is a pure
            // function, and every input is still in hand and unchanged at this point
            // (the stash below overwrites the entry), so this reproduces the
            // injector's own decision exactly rather than mirroring it.  The
            // SkipInnov branch is an invariant #1 event response (receiver reset or
            // firmware bias jump: withhold the fold, let the harvest re-seed), so it
            // is the RESPONDED positive control for this family.
            if (prires_rxcb && prires_est.enabled()) {
                const auto pit = rx_cb_carry.find({static_cast<int>(i), cb_key});
                if (pit != rx_cb_carry.end()) {
                    const double cgap = pl_now_s - pit->second.last_seen_s;
                    const double cinnov = pit->second.value_abs - cx_lin;
                    double cvar_eff = 0.0;
                    const RxCbInjectAction cact = rxCbInjectGate(
                        cgap, kRxCbMaxGapS, pit->second.var, ctx.knobs.rx_cb_q,
                        cinnov, /*k_sigma=*/10.0, /*guard_var=*/0.25, cvar_eff);
                    // SkipGap leaves cvar_eff at 0 (the gate returns before setting
                    // it), so there is no fold variance to standardize against: fall
                    // back to the nominal recompute and mark the row as raw formal
                    // (var_nominal) rather than invent a scale.
                    const bool have_var = cvar_eff > 0.0;
                    NetworkPriorResidual::Input in;
                    in.family   = "rxcb";
                    in.signal   = cb_key;
                    in.station  = static_cast<int>(i);
                    in.e        = pit->second.value_abs - value_abs;
                    in.fold_var = have_var
                        ? cvar_eff
                        : pit->second.var
                            + ctx.knobs.rx_cb_q * std::max(0.0, cgap);
                    in.post_var = var;
                    in.gap_s    = std::max(0.0, cgap);
                    in.folded   = (cact == RxCbInjectAction::Fold);
                    in.var_nominal = !have_var;
                    in.label = (cact == RxCbInjectAction::SkipInnov)
                                   ? PriorResidualLabel::Responded
                                   : PriorResidualLabel::Clean;
                    in.mech  = (cact == RxCbInjectAction::SkipInnov) ? "innov_withhold"
                             : (cact == RxCbInjectAction::SkipGap)   ? "gap" : "";
                    prires_est.addRow(in);
                }
            }
            rx_cb_carry[{static_cast<int>(i), cb_key}] =
                LocalCarry{value_abs, var, pl_now_s};
            ++ctx.counters.rx_cb_harvested_total;
        }
    }
    // The horizon is the registry's (kRxCbMaxGapS, the same constant; card PRM phase 3b).
    carryGapPrune(rx_cb_carry, pl_now_s,
                  ctx.params.spec(NetworkParamKind::RxCodeBias).gap_horizon_s,
                  [&](const auto&) {
                      prmRespond(ctx.counters.prm_resp, ResponseSite::RxcbGapPrune);   // card PRM phase 3a
                  });
}

